from pathlib import Path

SECTION = Path("results") / "section7.md"
README = Path("README.md")

HEADER = (
    "# DOTA 2 AI Assistant\n"
    "\n"
    "This README is maintained automatically. "
    "Section 7 is generated by `scripts/update_readme.py`.\n"
    "\n"
)


def main() -> int:
    if not SECTION.exists():
        print("missing", SECTION.as_posix())
        return 1

    section_text = SECTION.read_text(encoding="utf-8").rstrip()
    if not section_text:
        print("empty", SECTION.as_posix())
        return 1

    README.write_text(HEADER + section_text + "\n", encoding="utf-8")

    print("readme", README.as_posix())
    print("action rewritten")
    print("section_chars", len(section_text))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
